// Shared Live Scan / DriveScan engine. No automatic demo detections.
const demoAccounts={citizen:{name:'Aarav Sharma',email:'citizen@civiceye.demo',password:'Citizen@123',title:'Citizen login',description:'Report local issues and follow their resolution.'},authority:{name:'Municipal Authority',email:'authority@civiceye.demo',password:'Authority@123',title:'Authority login',description:'Prioritize incidents, assign teams, and review repairs.'},worker:{name:'Road Team A',email:'worker@civiceye.demo',password:'Worker@123',title:'Field worker login',description:'Accept assignments, update progress, and document repairs.'}};
function login(){const role=state.page.startsWith('login-')?state.page.slice(6):state.loginRole||'citizen',a=demoAccounts[role]||demoAccounts.citizen;state.loginRole=role;return `<div class="login-layout"><aside class="login-aside"><a class="logo" href="#home"><img src="favicon.svg" alt="">CivicEye <em>AI</em></a><div><div class="eyebrow" style="color:#6fd7c1">${role==='citizen'?'Your neighborhood, connected':role==='authority'?'Municipal command center':'Field operations'}</div><h1>${role==='citizen'?'A better city<br>starts with you.':role==='authority'?'Clear priorities.<br>Coordinated action.':'Every repair.<br>A visible difference.'}</h1><p>${a.description}</p></div><p>See. Detect. Prioritize. Resolve.</p></aside><section class="login-form"><div class="eyebrow">${state.live?'Secure account access':'Demo workspace'}</div><h1>${a.title}</h1><p>${a.description}</p><div class="role-choices">${[['citizen','users','Citizen'],['authority','grid','Authority'],['worker','briefcase','Field worker']].map(([r,i,l])=>`<button class="role-choice ${role===r?'active':''}" data-role="${r}">${icon(i)}${l}</button>`).join('')}</div><form id="${state.live?'login-form':'demo-login-form'}"><label class="field">Email<input name="email" type="email" autocomplete="username" placeholder="${state.live?'Your account email':a.email}" required></label><label class="field">Password<input name="password" type="password" autocomplete="current-password" minlength="8" required></label><div id="login-error" class="login-error" role="alert"></div><button class="btn primary full" type="submit">${state.live?'Sign in':'Sign in to demo'}</button></form>${state.live?`<p class="subtext">Your account profile determines access. Selecting a role cannot grant it.</p>${role==='citizen'?'<button class="button-link" id="signup">Create a citizen account</button>':''}`:`<div class="demo-credentials"><div class="row-title"><b>Demo credentials</b><span class="badge demo">DEMO ONLY</span></div><dl><dt>Email</dt><dd>${a.email}</dd><dt>Password</dt><dd>${a.password}</dd></dl><button class="btn full" id="fill-demo">Use demo credentials</button><p class="subtext">Sample account · no real authentication. Local records are saved on this browser. Image findings are simulated unless a vision API is connected.</p></div>`}<div class="divider">CITIZENS · AUTHORITIES · FIELD TEAMS</div><button class="btn full" id="connection-login">${icon('settings')}Connect live services</button><a class="button-link" href="#home" style="display:block;text-align:center;margin-top:20px">Back to CivicEye</a></section></div>`}
function bind(){legacyBind();document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{state.loginRole=b.dataset.role;navigate('login-'+b.dataset.role)});for(const [id,r]of [['citizen-login','citizen'],['hero-report','citizen'],['authority-login','authority']])if($('#'+id))$('#'+id).onclick=()=>{state.loginRole=r;navigate('login-'+r)};if($('#demo-login-form'))$('#demo-login-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),r=state.loginRole,a=demoAccounts[r];if(String(f.get('email')).trim().toLowerCase()!==a.email||f.get('password')!==a.password){$('#login-error').textContent='These credentials do not match this demo role. Use the demo credentials shown below.';return}state.role=r;state.user={id:r==='worker'?'demo-worker':'demo-'+r,name:a.name,email:a.email,role:r};navigate({citizen:'citizen',authority:'dashboard',worker:'tasks'}[r])};if($('#fill-demo'))$('#fill-demo').onclick=()=>{const a=demoAccounts[state.loginRole],form=$('#demo-login-form');form.elements.email.value=a.email;form.elements.password.value=a.password;$('#login-error').textContent='';form.querySelector('button[type="submit"]').focus()};if($('#signout'))$('#signout').onclick=async()=>{stopScan();clearInterval(pollTimer);if(client)await client.auth.signOut();state.role=null;state.user=null;navigate('home')};bindLiveScan();}
function navigate(page){stopScan();legacyNavigate(page)}
const beforeSecondary=secondary;secondary=function(){return ['live-scan','drivescan'].includes(state.page)?liveScanPage():beforeSecondary()};
const beforeSettings=settings;settings=function(){return beforeSettings()+`<section class="panel" style="max-width:760px;margin-top:24px"><div class="panel-head"><h2>Live Scan vision endpoint</h2><span class="badge ${visionReady()?'resolved':'demo'}">${visionReady()?'Configured':'Not connected'}</span></div><div class="panel-body"><p>Live Scan and DriveScan share this service. Connect an endpoint that accepts image frames and returns normalized bounding boxes. Without one, the camera works and no detections are generated.</p><form id="vision-settings"><label class="field">POST endpoint URL<input name="endpoint" placeholder="https://your-vision-service/api/vision/detect" value="${esc(state.config.visionEndpoint||'')}"></label><button class="btn primary">Save vision endpoint</button><button class="btn" type="button" id="clear-vision">Disconnect vision</button></form><p class="subtext">Only enter a service you trust with camera images. It must support browser CORS. Provider secrets belong on its server.</p></div></section>`};
let scan={active:false,paused:false,busy:false,timer:null,generation:0,facing:'environment',mode:'live',detections:[],feed:[],camera:false,model:false,status:'Live Scan ready — connect vision API',error:'',frameInterval:300,maxFrameDimension:640,timeout:15000,controller:null};
function visionReady(){return !!state.config.visionEndpoint||!!(client&&state.user&&state.live)}
function scanScene(){return ['live-scan','drivescan'].includes(state.page)}
function liveScanPage(){const drive=state.page==='drivescan';return header(drive?'DriveScan':'Live Scan',drive?'Observe the road with the shared civic vision engine.':'Point your camera at a visible civic issue. Review a finding before creating an incident.')+`<div class="scan-grid"><section class="panel"><div class="panel-head"><h2>${drive?'Road camera':'Live camera'}</h2><span id="live-status" class="badge status">Camera stopped</span></div><div class="panel-body"><div class="scan-viewport"><video id="live-camera" autoplay playsinline muted></video><div id="scan-placeholder">${icon('camera')}<h3>Your camera view</h3><p>Start the camera to scan your surroundings.</p></div><div id="detection-boxes" aria-hidden="true"></div><span class="scan-mode-label" id="scan-mode-label">LIVE SCAN</span><div class="scan-message" id="scan-message" aria-live="polite">LIVE SCAN READY — CONNECT VISION API</div></div><div class="scan-controls"><button class="btn primary" id="live-start">${icon('camera')}Start camera</button><button class="btn" id="live-switch">Switch camera</button><button class="btn" id="live-pause">Pause scan</button><button class="btn" id="live-stop">Stop camera</button><button class="btn" id="live-video-upload">Upload video</button><input type="file" id="live-video-file" accept="video/*" class="screen-reader" aria-label="Upload video for scan"></div><div class="scan-connections"><span id="camera-connection">Camera: disconnected</span><span id="model-connection">AI model: ${visionReady()?'configured':'offline'}</span><span id="location-connection">Location: ${state.position?'available':'not set'}</span><button class="button-link" id="live-location">Use location</button></div><div id="live-error" class="login-error" role="alert"></div><div id="current-detection"></div><div class="scan-demo-control"><label class="field">Scan mode<select id="scan-mode"><option value="live" ${scan.mode==='live'?'selected':''}>Live · real image analysis</option><option value="demo" ${scan.mode==='demo'?'selected':''}>Demo · manually staged result</option></select></label><div id="scan-demo-options" ${scan.mode==='demo'?'':'hidden'}><div class="notice"><b>DEMO MODE.</b> No AI analysis occurs. Boxes and confidence are illustrative and appear only when you explicitly stage a finding.</div><div class="actions"><select id="stage-type" aria-label="Simulated detection"><option value="pothole">Pothole</option><option value="garbage">Garbage</option><option value="waterlogging">Waterlogging</option><option value="none">No issue</option></select><button class="btn" id="stage-demo">Show selected demo finding</button></div></div></div><p class="subtext">Visual size and water coverage are estimates. A normal camera does not measure exact water depth or physical dimensions.${drive?' Operate only as a passenger or while safely parked.':''}</p></div></section><section class="panel"><div class="panel-head"><h2>Live detections</h2><span class="subtext" id="feed-count">${scan.feed.length} findings</span></div><div id="live-feed">${liveFeedHtml()}</div><div class="panel-body"><p class="subtext">Repeated frames do not create reports. Select “Create incident” to save a frame and check nearby duplicates.</p></div></section></div>`}
function displayType(c){return {pothole:'Pothole',garbage:'Garbage',waterlogging:'Waterlogging'}[c]||'None'}
function waterSeverity(n){return n<=15?'LOW':n<=35?'MEDIUM':n<60?'HIGH':'CRITICAL'}
function liveFeedHtml(){return scan.feed.map((f,n)=>`<div class="queue-row"><div class="issue-icon ${displayType(f.detection.class)}">${typeIcon(displayType(f.detection.class))}</div><div class="row-body"><div class="row-title">${displayType(f.detection.class)}${badge(f.detection.severity)}</div><p>${esc(confidenceText(f.detection))} ${f.demo?'illustrative confidence · DEMO':'visual assessment'}</p>${f.detection.surfaceCoverage===undefined?'':`<p>Estimated Visual Water Coverage: ${f.detection.surfaceCoverage}%</p>`}<div class="row-meta"><span>${new Date(f.time).toLocaleTimeString('en-IN')}</span><button class="button-link" data-live-incident="${n}">Create incident</button></div></div></div>`).join('')||'<div class="empty">No findings yet. Camera frames never create incidents automatically.</div>'}
function validateDetectionResponse(data){if(!data||!Array.isArray(data.detections))throw Error('Vision service returned an invalid detection response.');return data.detections.map(d=>{const cls=String(d.class||'').toLowerCase();if(!['pothole','garbage','waterlogging'].includes(cls)||!(Number.isFinite(d.confidence)&&d.confidence>=0&&d.confidence<=1)&&!(d.confidence===null&&['High confidence','Likely','Needs review'].includes(d.confidence_label)))throw Error('Vision service returned invalid confidence or issue class.');const severity=String(d.severity||'medium').toUpperCase();if(!['LOW','MEDIUM','HIGH','CRITICAL'].includes(severity))throw Error('Vision service returned invalid severity.');const result={class:cls,detector:['civiceye-v2','pothole-specialist'].includes(d.detector)?d.detector:undefined,confidence:d.confidence,confidence_label:d.confidence_label,requires_review:d.requires_review===true,severity,explanation:d.explanation||'Visible '+cls+' reported by the connected vision service.'};if(d.bbox){const b=d.bbox;if(!['x','y','width','height'].every(k=>Number.isFinite(b[k]))||b.x<0||b.y<0||b.width<=0||b.height<=0||b.x+b.width>1.001||b.y+b.height>1.001)throw Error('Vision bounding boxes must use valid normalized coordinates.');result.bbox={...b}}if(cls==='waterlogging'&&d.surfaceCoverage!==undefined){if(!Number.isFinite(d.surfaceCoverage)||d.surfaceCoverage<0||d.surfaceCoverage>100)throw Error('Invalid estimated visual surface coverage.');result.surfaceCoverage=Math.round(d.surfaceCoverage*10)/10;result.severity=waterSeverity(d.surfaceCoverage)}return result})}
async function detectFrame(image,signal){if(state.config.visionEndpoint){const r=await fetch(state.config.visionEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image,timestamp:now(),frame:{coordinates:'normalized'}}),signal});if(!r.ok)throw Error(`AI detection service unavailable (${r.status}).`);return {detections:validateDetectionResponse(await r.json())}}if(client&&state.user&&state.live){const a=await analyze(image);return {detections:a.issue_type==='None'?[]:[{class:a.issue_type.toLowerCase(),confidence:a.confidence,severity:a.severity,explanation:a.explanation}],analysis:a};}throw Error('AI model not connected. Configure a vision API in Connections.')}
async function startLiveCamera(){stopScan();scan.error='';const generation=scan.generation;try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera unavailable. Use image reporting or open this app over HTTPS.');const next=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:scan.facing},width:{ideal:1280},height:{ideal:720}},audio:false});if(generation!==scan.generation||!scanScene()){next.getTracks().forEach(t=>t.stop());return}stream=next;const video=$('#live-camera');video.controls=false;video.srcObject=stream;await video.play();video.parentElement.style.aspectRatio=video.videoWidth+'/'+video.videoHeight;video.onresize=()=>{video.parentElement.style.aspectRatio=video.videoWidth+'/'+video.videoHeight};scan.camera=true;scan.active=true;scan.paused=false;scan.model=false;scan.status=scan.mode==='demo'?'DEMO MODE — choose a staged finding':visionReady()?'Scanning…':'AI MODEL NOT CONNECTED';$('#scan-placeholder').hidden=true;updateScanUi();if(scan.mode==='live'&&visionReady())scheduleScan(0)}catch(e){if(generation!==scan.generation)return;stream?.getTracks().forEach(t=>t.stop());stream=null;scan.camera=false;scan.active=false;scan.error=e.name==='NotAllowedError'?'Camera permission is required for Live Scan. Allow camera access or use image reporting.':e.name==='NotFoundError'?'No camera found. Connect a camera or use image reporting.':e.name==='NotReadableError'?'The camera is busy in another app. Close it there and try again.':e.message;scan.status='Camera unavailable';updateScanUi()}}
function stopScan(){clearScanHistory();if(scan.videoUrl){URL.revokeObjectURL(scan.videoUrl);scan.videoUrl=null}clearTimeout(scan.timer);scan.controller?.abort();scan.controller=null;scan.generation++;scan.active=false;scan.camera=false;scan.paused=false;scan.busy=false;scan.detections=[];stream?.getTracks().forEach(t=>t.stop());stream=null;if($('#live-camera')){$('#live-camera').pause();$('#live-camera').srcObject=null;$('#live-camera').removeAttribute('src');$('#scan-placeholder').hidden=false;scan.status='Camera stopped';updateScanUi()}}
const frameCanvas=document.createElement('canvas'),frameContext=frameCanvas.getContext('2d');
const bestCanvas=document.createElement('canvas'),bestContext=bestCanvas.getContext('2d');
const sharpCanvas=document.createElement('canvas'),sharpContext=sharpCanvas.getContext('2d',{willReadFrequently:true});
const scanStabilizer=new CivicMotion.Stabilizer();
let persistenceTimer=null;
function clearScanHistory(){clearTimeout(persistenceTimer);scanStabilizer.reset();scan.detections=[];}
function captureCanvas(){
  const v=$('#live-camera');if(!v?.videoWidth)throw Error('Wait for the camera to show a frame.');
  const scale=Math.min(1,scan.maxFrameDimension/Math.max(v.videoWidth,v.videoHeight));
  const w=Math.round(v.videoWidth*scale),h=Math.round(v.videoHeight*scale);
  if(frameCanvas.width!==w||frameCanvas.height!==h){frameCanvas.width=w;frameCanvas.height=h;bestCanvas.width=w;bestCanvas.height=h;}
  frameContext.drawImage(v,0,0,w,h);return frameCanvas;
}
function liveFrame(){return captureCanvas().toDataURL('image/jpeg',.8);}
function burstWait(signal){return new Promise((resolve,reject)=>{
  if(signal.aborted)return reject(new DOMException('Capture cancelled','AbortError'));
  const abort=()=>{clearTimeout(timer);reject(new DOMException('Capture cancelled','AbortError'));};
  const timer=setTimeout(()=>{signal.removeEventListener('abort',abort);resolve();},80);
  signal.addEventListener('abort',abort,{once:true});
});}
async function sharpestFrame(signal,generation){
  let bestScore=-1;
  for(let i=0;i<3;i++){
    if(i)await burstWait(signal);
    if(signal.aborted||generation!==scan.generation||scan.paused||!scan.active||scan.mode!=='live')throw new DOMException('Capture cancelled','AbortError');
    captureCanvas();
    const w=160,h=Math.max(3,Math.round(160*frameCanvas.height/frameCanvas.width));
    if(sharpCanvas.width!==w||sharpCanvas.height!==h){sharpCanvas.width=w;sharpCanvas.height=h;}
    sharpContext.drawImage(frameCanvas,0,0,w,h);
    const score=CivicMotion.sharpness(sharpContext.getImageData(0,0,w,h).data,w,h);
    if(score>bestScore){bestScore=score;bestContext.drawImage(frameCanvas,0,0);}
  }
  const blob=await new Promise(resolve=>bestCanvas.toBlob(resolve,'image/jpeg',.8));
  if(!blob)throw Error('Camera frame could not be encoded.');
  const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});
  scan.captureMetrics={jpegBytes:blob.size,sharpness:bestScore};return image;
}
function scheduleScan(delay){clearTimeout(scan.timer);if(scan.active&&!scan.paused&&scan.mode==='live')scan.timer=setTimeout(()=>{scan.timer=null;scanTick();},delay)}
async function scanTick(){
  if(!scan.active||scan.paused||scan.busy||scan.mode!=='live')return;
  const generation=scan.generation;scan.busy=true;
  const started=performance.now(),controller=new AbortController();scan.controller=controller;
  const timeout=setTimeout(()=>controller.abort(),scan.timeout);let failed=false;
  try{
    if(!navigator.onLine)throw Error('No internet connection. Reconnect to resume detection.');
    const image=await sharpestFrame(controller.signal,generation);
    if(controller.signal.aborted||generation!==scan.generation||scan.paused||!scan.active)return;
    const response=await detectFrame(image,controller.signal);
    if(generation!==scan.generation||!scan.active||scan.paused||scan.mode!=='live')return;
    scan.model=true;scan.error='';
    const stabilized=scanStabilizer.update(response.detections,performance.now());
    scan.detections=stabilized.display;
    scan.status=stabilized.fresh.length?'Civic issue detected':scan.detections.length?'Recent detection — awaiting next frame':response.detections.length?'Confirming detection…':'NO CIVIC ISSUE DETECTED';
    stabilized.fresh.forEach(d=>saveFinding(d,image,false,response.analysis));
    clearTimeout(persistenceTimer);
    if(scan.detections.length)persistenceTimer=setTimeout(()=>{
      if(generation!==scan.generation||scan.paused||!scan.active)return;
      scan.detections=scanStabilizer.expire(performance.now());
      if(!scan.detections.length)scan.status='Scanning…';updateScanUi();
    },Math.max(1,scanStabilizer.expires-performance.now()+5));
    scan.requestMetrics={...scan.captureMetrics,totalMs:performance.now()-started,backendMs:response.processingTimeMs};
    updateScanUi();
  }catch(e){
    failed=true;
    if(generation===scan.generation&&scan.active&&!scan.paused&&scan.mode==='live'){
      scan.model=false;clearScanHistory();scan.status='Detection temporarily unavailable';
      scan.error=e.name==='AbortError'?'Detection timed out. The scan will retry.':e.message;updateScanUi();
    }
  }finally{
    clearTimeout(timeout);
    if(generation===scan.generation){scan.busy=false;scan.controller=null;scheduleScan(CivicMotion.nextDelay(performance.now()-started,failed));}
  }
}
function saveFinding(d,image,demo,analysis){const recent=scan.feed.find(f=>f.detection.class===d.class&&f.demo===demo&&Date.now()-new Date(f.time)<10000);if(recent){if(d.confidence>recent.detection.confidence){recent.detection=d;recent.image=image;recent.analysis=analysis}recent.lastSeen=now();return}scan.feed.unshift({detection:d,image,demo,time:now(),analysis,latitude:state.position?.latitude,longitude:state.position?.longitude});scan.feed=scan.feed.slice(0,30)}
function updateScanUi(){if(!scanScene()||!$('#live-status'))return;$('#live-status').textContent=scan.camera?(scan.paused?'Scan paused':scan.mode==='demo'?'DEMO MODE':'LIVE SCAN ACTIVE'):'Camera stopped';$('#scan-mode-label').textContent=scan.mode==='demo'?'DEMO MODE':'LIVE SCAN';$('#scan-message').textContent=scan.status;$('#live-error').textContent=scan.error;$('#camera-connection').textContent='Camera: '+(scan.camera?'connected':'disconnected');$('#model-connection').textContent='AI model: '+(scan.mode==='demo'?'demo — not analyzed':scan.model?'connected':visionReady()?'configured, awaiting response':'offline');$('#location-connection').textContent='Location: '+(state.position?'available':'not set');$('#live-pause').textContent=scan.paused?'Resume scan':'Pause scan';if(typeof drawVisionOverlay!=='function')$('#detection-boxes').innerHTML=scan.detections.filter(d=>d.bbox).map(d=>`<div class="detection-box ${d.class}" style="left:${d.bbox.x*100}%;top:${d.bbox.y*100}%;width:${d.bbox.width*100}%;height:${d.bbox.height*100}%"><span>${displayType(d.class).toUpperCase()} ${esc(confidenceText(d))}${scan.mode==='demo'?' · DEMO':''}</span></div>`).join('');$('#current-detection').innerHTML=scan.detections.map(d=>`<div class="scan-finding"><div class="row-title"><h3>${displayType(d.class)} detected</h3>${badge(d.severity)}</div><p>${esc(confidenceText(d))} ${scan.mode==='demo'?'illustrative':'model'} confidence${d.surfaceCoverage===undefined?'':` · Estimated Visual Water Coverage: ${d.surfaceCoverage}%`}</p>${d.class==='waterlogging'?'<p class="subtext">Standing water — possible drainage issue. Hidden blockage is not confirmed.</p>':''}${!d.bbox&&scan.mode==='live'?'<p class="subtext">This service did not return a bounding box.</p>':''}</div>`).join('');$('#live-feed').innerHTML=liveFeedHtml();$('#feed-count').textContent=scan.feed.length+' findings';bindLiveFeed()}
function bindLiveFeed(){document.querySelectorAll('[data-live-incident]').forEach(b=>b.onclick=()=>{const f=scan.feed[Number(b.dataset.liveIncident)],d=f.detection;stopScan();state.report={image:f.image,analysis:f.analysis||{issue_type:displayType(d.class),confidence:d.confidence,confidence_label:d.confidence_label,requires_review:d.requires_review===true,severity:d.severity==='CRITICAL'?'HIGH':d.severity,explanation:d.explanation,demo:f.demo,source:f.demo?'explicit-demo':'onnx-api',detector:d.detector,surfaceCoverage:d.surfaceCoverage},latitude:f.latitude,longitude:f.longitude,captured_at:f.time,scan_context:{capturedAt:f.time,surfaceCoverage:d.surfaceCoverage,severity:d.severity,issueType:displayType(d.class),confidence:d.confidence,confidence_label:d.confidence_label}};navigate('report');toast('Frame saved. Add the location and review the incident before submitting.')})}
function bindLiveScan(){if($('#vision-settings'))$('#vision-settings').onsubmit=e=>{e.preventDefault();safe(async()=>{const value=String(new FormData(e.target).get('endpoint')).trim();if(value){const url=new URL(value,location.origin);if(url.protocol!=='https:'&&!(url.protocol==='http:'&&['localhost','127.0.0.1'].includes(url.hostname)))throw Error('Use HTTPS for the vision endpoint (or localhost for development).');state.config.visionEndpoint=url.href}else delete state.config.visionEndpoint;localStorage.setItem('civiceye-public-settings',JSON.stringify(state.config));render();toast('Vision endpoint saved')})};if($('#clear-vision'))$('#clear-vision').onclick=()=>{delete state.config.visionEndpoint;localStorage.setItem('civiceye-public-settings',JSON.stringify(state.config));render()};if(!scanScene())return;$('#live-video-upload').onclick=()=>$('#live-video-file').click();$('#live-video-file').onchange=()=>safe(async()=>{const file=$('#live-video-file').files[0];if(!file?.type.startsWith('video/'))throw Error('Choose a video file.');stopScan();const video=$('#live-camera');scan.videoUrl=URL.createObjectURL(file);video.src=scan.videoUrl;video.controls=true;video.loop=true;await video.play();video.parentElement.style.aspectRatio=video.videoWidth+'/'+video.videoHeight;scan.camera=true;scan.active=true;scan.status=scan.mode==='demo'?'DEMO MODE — choose a staged finding':visionReady()?'Scanning uploaded video…':'AI MODEL NOT CONNECTED';$('#scan-placeholder').hidden=true;updateScanUi();if(scan.mode==='live'&&visionReady())scheduleScan(0)});$('#live-start').onclick=startLiveCamera;$('#live-stop').onclick=stopScan;$('#live-switch').onclick=()=>{scan.facing=scan.facing==='environment'?'user':'environment';startLiveCamera()};$('#live-pause').onclick=()=>{if(!scan.camera)return toast('Start the camera first.');scan.paused=!scan.paused;clearScanHistory();if(scan.paused)scan.controller?.abort();clearTimeout(scan.timer);scan.status=scan.paused?'Scan paused':scan.mode==='demo'?'DEMO MODE — choose a staged finding':visionReady()?'Scanning…':'AI MODEL NOT CONNECTED';updateScanUi();if(!scan.paused&&visionReady())scheduleScan(0)};$('#live-location').onclick=()=>safe(async()=>{state.position=await geolocate();updateScanUi()});$('#scan-mode').onchange=e=>{scan.mode=e.target.value;clearScanHistory();scan.controller?.abort();clearTimeout(scan.timer);$('#scan-demo-options').hidden=scan.mode!=='demo';scan.status=scan.mode==='demo'?'DEMO MODE — choose a staged finding':visionReady()?'Scanning…':'AI MODEL NOT CONNECTED';updateScanUi();if(scan.mode==='live'&&scan.camera&&visionReady())scheduleScan(0)};$('#stage-demo').onclick=()=>safe(async()=>{if(!scan.camera)throw Error('Start the camera before staging a demo finding.');const cls=$('#stage-type').value;scan.detections=cls==='none'?[]:[{class:cls,confidence:.94,severity:'MEDIUM',bbox:{x:.2,y:.3,width:.45,height:.4},...(cls==='waterlogging'?{surfaceCoverage:27}:{}),explanation:'Explicitly staged demo finding. No AI analysis performed.'}];scan.status=cls==='none'?'DEMO: NO CIVIC ISSUE DETECTED':'DEMO: '+displayType(cls).toUpperCase()+' DETECTED';scan.detections.forEach(d=>saveFinding(d,liveFrame(),true,null));updateScanUi()});bindLiveFeed();updateScanUi()}
const previousAnalysisCard=analysisCard;analysisCard=function(r){const c=r.scan_context;return previousAnalysisCard(r)+(c?`<div class="notice" style="margin-top:15px"><b>Saved scan frame</b><br>${esc(c.issueType)} · ${esc(c.severity)} estimated visual severity · ${esc(confidenceText(c))} assessment${c.surfaceCoverage===undefined?'':`<br>Estimated Visual Water Coverage: ${c.surfaceCoverage}%`}<br>Captured ${new Date(c.capturedAt).toLocaleString('en-IN')}</div>`:'')};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&scan.camera)stopScan()});window.addEventListener('pagehide',stopScan);render();
